def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    colors = set(v for _, _, v in points)
    k = len(colors)

    forms = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: r - c,
    ]

    for coord in forms:
        color_residues = {}
        valid = True
        for r, c, color in points:
            residue = coord(r, c) % k
            if color in color_residues and color_residues[color] != residue:
                valid = False
                break
            color_residues[color] = residue
        if valid and len(set(color_residues.values())) == k:
            residue_colors = {residue: color for color, residue in color_residues.items()}
            return [[residue_colors[coord(r, c) % k] for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
